import json
import xml.etree.ElementTree as ET

root = ET.fromstring('<rss><channel><title>Daily Code</title><item><link>https://example.com/1</link><pubDate>2024-05-01</pubDate></item></channel></rss>')
channel = root.find("channel")
feed = {
    "title": channel.findtext("title"),
    "items": [
        {"link": item.findtext("link"), "pubDate": item.findtext("pubDate")}
        for item in channel.findall("item")
    ],
}
print(json.dumps(feed, indent=2))

