import json
import xml.etree.ElementTree as ET

ns = {"xlink": "http://www.w3.org/1999/xlink"}
root = ET.fromstring('<link xmlns:xlink="http://www.w3.org/1999/xlink" xlink:href="/docs/api">API</link>')
obj = {"text": root.text, "xlink:href": root.get("{http://www.w3.org/1999/xlink}href")}
print(json.dumps({root.tag: obj}, indent=2))

